var i=`0493-yabrak`;var t=`world-0493`;var a=`SY`;var r=`western-asia`;var o=4;var l=110;var s={en:`Yabrak`,ua:`Ябрак`};var g={en:`A traditional dish from Syria, centered on grape leaves, ground lamb, white rice, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Сирія. Основні складники: виноградне листя, фарш з ягнятини, білий рис, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var c=[{en:`Separate and blanch the leaves in hot water for about 8 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 8 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:8,i:[[`grape-leaves`,50,`pcs`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,350,`g`],[`white-rice`,240,`g`],[`yellow-onion`,160,`g`],[`allspice-berries`,4,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:20,i:[]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 70 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 70 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:70,i:[[`water`,650,`ml`],[`lemon-juice`,60,`ml`],[`garlic`,5,`clove`]]}];var d={slug:i,id:t,country:`SY`,region:r,servings:4,minutes:110,title:s,text:g,steps:c};export{a as country,d as default,t as id,l as minutes,r as region,o as servings,i as slug,c as steps,g as text,s as title};